mapper.select:
select cct.code_type ,cct.code_type_nm ,cct.code_type_nm_s ,cct.start_date ,cct.end_date ,cct.create_type_cd ,cct.remark ,cct.create_date ,cct.create_by ,cct.update_date ,cct.update_by ,cct.rowid from com_code_type cct where 1=1
and cct.code_type = #{CODE_TYPE}
and cct.code_type_nm like #{CODE_TYPE_NM} || '%'

mapper.delete:
delete from com_code_type cct
 where 1=1
   and cct.code_type = #{CODE_TYPE}
